CREATE TABLE rejeu (horodatage TIMESTAMP(0), host VARCHAR2(50), domaine VARCHAR2(200), ip_dest VARCHAR2(50));
CREATE TABLE alertes (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, horodatage TIMESTAMP(0), host VARCHAR2(50), cible VARCHAR2(200));
CREATE OR REPLACE TRIGGER trg_rejeu
AFTER INSERT ON rejeu
FOR EACH ROW
BEGIN
  INSERT INTO alertes (horodatage, host, cible)
  SELECT :NEW.horodatage, :NEW.host, :NEW.domaine FROM dual
  WHERE :NEW.domaine IN (SELECT valeur FROM ioc WHERE type = 'domaine')
     OR :NEW.ip_dest IN (SELECT valeur FROM ioc WHERE type = 'ip');
END;
INSERT INTO rejeu (horodatage, host, domaine, ip_dest) SELECT horodatage, host, domaine, ip_dest FROM proxy_logs ORDER BY horodatage;
SELECT host, MIN(horodatage) AS premiere, COUNT(*) AS alertes FROM alertes GROUP BY host ORDER BY premiere;
